import{_ as t,C as l,o as n,c as s,a6 as i,E as c,j as a,a as o}from"./chunks/framework.CKIbuWFA.js";const g=JSON.parse('{"title":"准备协作与团队访问","description":"","frontmatter":{"title":"准备协作与团队访问","docId":"user.cloud.collaboration","translationKey":"user.cloud.collaboration","locale":"zh","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4a97f64b6bdc818ebb8d16eec1e67d95a2d0eae0b75f7cfd5c1493bf27244684","translationRevision":"2cbe901be7ab6ec1b6458d4135506c0d06d677dc434e31295d5af37d15879be8","order":30},"headers":[],"relativePath":"zh/user/cloud/collaboration.md","filePath":"zh/user/cloud/collaboration.md","lastUpdated":1794611623000}'),d={name:"zh/user/cloud/collaboration.md"};function u(p,e,h,b,m,f){const r=l("DemoFrame");return n(),s("div",null,[e[0]||(e[0]=i('<h1 id="prepare-collaboration-and-team-access" tabindex="-1">准备协作与团队访问 <a class="header-anchor" href="#prepare-collaboration-and-team-access" aria-label="Permalink to &quot;准备协作与团队访问 {#prepare-collaboration-and-team-access}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>为另一位操作员授予明确角色，同时保留所有者控制权。你需要具备相应能力的桌面宿主，并明确选择本地/原生协作，或基于账户的团队。团队还需要<a href="./account.html">登录 Cloud</a>及匹配的已部署服务支持。请从只读访问和非生产环境开始。</p><h2 id="configure-owner-access" tabindex="-1">配置所有者访问控制 <a class="header-anchor" href="#configure-owner-access" aria-label="Permalink to &quot;配置所有者访问控制 {#configure-owner-access}&quot;">​</a></h2><ol><li>打开 <strong>设置 → 协作</strong>。检查连接状态，并通过控件启用或配置所需监听器或网关。</li><li>创建邀请前，审查允许的来源及访问矩阵。只选择操作员所需的区域、操作与资源。</li><li>创建邀请，通过可信渠道传递私有链接或令牌。邀请并不等于已批准的活动会话。</li><li>检查待处理请求及请求的授权。仅批准预期操作员，再确认其可见身份及连接。</li><li>使用访问检查器审查后续授权变更。不再需要访问时，撤销邀请、身份或会话。</li></ol><p>委托编辑定义、以所有者身份采纳定义，以及批准委托执行，是不同的决定。请在具体审查中阅读保存的源码、引用操作及权限。仅有定义预览并不授权执行效果。</p><h2 id="prepare-an-account-based-team" tabindex="-1">准备基于账户的团队 <a class="header-anchor" href="#prepare-an-account-based-team" aria-label="Permalink to &quot;准备基于账户的团队 {#prepare-an-account-based-team}&quot;">​</a></h2><p>若提供 <strong>设置 → 团队</strong>，请创建有名称的团队并选中它。使用易识别的设备标签将 <strong>此电脑</strong> 注册为宿主，再使用 <strong>开始提供服务</strong> 并检查链路状态。前端已连接团队创建与本地宿主注册流程；这些操作不同于邀请队友。控制端设备有独立的注册角色。</p><p>选择收件人、角色及邀请有效期，然后审查收到的请求、成员和设备。昵称搜索需要单独部署的后端端点，当前服务可能不提供。搜索失败不代表对方没有账户，也不要用任意 ID 代替选择来绕过流程。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>所有者访问控件及前端团队创建/注册功能已存在。完整远程协作流程仍属实验性：真实双电脑直播操作、生产昵称查询、NAT/中继行为，以及各平台和效果恢复路径，均未在此确立。链路就绪本身不能证明预期操作的端到端权限执行正确。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>授权或宿主修订过期时，重新加载并再次审查。命令未确认时，重试前先检查已记录结果。会话结束时停止服务或撤销访问。不要在公开<a href="./../preferences/troubleshooting.html">诊断报告</a>中包含邀请令牌或凭据。</p>',13)),c(r,{scenario:"collaboration",locale:"zh",title:"演示：协作"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[o("运行细节 "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "运行细节 {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,[o("加入或批准 Teams 访问后，宿主还须确认原生权限的当前修订。"),a("code",null,"pendingHost"),o(" 表示仍待确认；活动传输或团队成员身份本身不授予原生访问。权限变化后重新加载并核对宿主/设备状态。observer 以读取为主；moderator 增加指定运行控制，automationEditor 增加指定编辑，custom 要求明确审核的策略。任何角色都不授予无限脚本/外部副作用。界面无法解释拒绝时，参见"),a("a",{href:"./../../developer/collaboration.html#operational-details"},"角色及确认契约"),o("。")],-1))])}const q=t(d,[["render",u]]);export{g as __pageData,q as default};
